node --input-type=module <<'JS'
import { registerHooks } from 'node:module';
import { existsSync } from 'node:fs';
registerHooks({resolve(spec, ctx, next) {
  if (spec === '../dist/typed/vendor.js') return next('../src/typed/vendor.ts', ctx);
  if (ctx.parentURL?.endsWith('.ts') && spec.startsWith('.') && spec.endsWith('.js')) {
    const url = new URL(spec.slice(0,-3) + '.ts', ctx.parentURL);
    if (existsSync(url)) return next(url.href, ctx);
  }
  return next(spec, ctx);
}});
const {installVendor} = await import('./tools/node-vendor.mjs');
await installVendor({reference:true});
const {Program} = await import('./src/typed/program.ts');
const {projectSource} = await import('./src/typed/project.ts');
const {storeOf} = await import('./src/typed/ir.ts');
const {casesFrom,evaluate,readBuffer} = await import('./src/typed/evaluate.ts');
const {runImage,imageFromCode} = await import('./src/typed/backend/index.ts');
const assert = (await import('node:assert/strict')).default;
const source = \`
value record Four { a: i32; b: i32; c: i32; d: i32; }
function spin(x: i32, n: i32): i32 { return (x >>> n) | (x << (32 - n)); }
function mix(a: i32, b: i32, c: i32, d: i32): Four {
    return Four(a + b, a ^ -1, spin(c, 7), d);
}
function probe(input: buffer, out: buffer): i32 {
    const tmp = new Int32Array(64);
    for (let i = 0; i < input.length / 2; i = i + 1) {
        tmp[i] = input.charCodeAt(2 * i) | (input.charCodeAt(2 * i + 1) << 16);
    }
    const r = mix(tmp[0], 1, tmp[0], 0xdeadbeef);
    out.setCharCodeAt(0, r.a & 65535);
    out.setCharCodeAt(1, r.a >>> 16);
    out.setCharCodeAt(2, r.b & 65535);
    out.setCharCodeAt(3, r.c & 65535);
    out.setCharCodeAt(4, r.d >>> 16);
    return r.d;
}\`;
const inputs = {probe:{input:{cells:[65535,32767]},out:{buffer:[5,5],cell:[0,0]}},spin:{n:{oneOf:[2,7,25]} }};
const meta = {sources:['main.typed'],pipeline:'speed',focus:7,inputs};
const ps=projectSource('probe',{'main.typed':source,'project.json':JSON.stringify(meta)});
const p=Program.fromProject(ps);
assert.equal(p.status,'ok',JSON.stringify(p.error));
assert.equal(p.options.entries,undefined);
const st=storeOf(p.origin.value);
const [c]=casesFrom(st,'probe',{count:1,inputs:p.inputs.probe});
const run={base:evaluate(st,'probe',c.args,c.memory,{limit:2e4})};
const ref=globalThis.typedRv32.compile(ps.source,[],undefined);
run.ref=runImage(imageFromCode('probe',ref.image,ref.entries),'probe',c.args,c.memory);
const revisions=await p.pipeline('speed');
const img=p.compile({coalesce:true,chains:true,homes:true});
run.optimized=img.run('probe', [[65535,32767],[0,0,0,0,0]]);
const out=c.items.find(x=>x.name==='out');
const expected=[0,32768,0,65535,57005];
for(const [mode,r] of Object.entries(run)){
 const cells=r.bytes?readBuffer(r.bytes,out.at):r.buffers.find(x=>x.name==='out').cells;
 console.log(mode,r.result,r.trap,r.steps,r.unit,cells);
 assert.equal(r.trap,false); assert.equal(r.result,0xdeadbeef|0); assert.deepEqual(cells,expected);
}
console.log('pipeline',JSON.stringify(revisions));
console.log('check',JSON.stringify(p.check({count:4})));
const h=await import('./src/framework/core/data.ts');
console.log('sha oracle',h.sha256(''),h.sha256('abc'));
